#[ignore="requires real compiled desktop archive worker"]
async fn cp06dr2_supervised_archive_actual_output(){let worker=PathBuf::from(std::env::var("LU_CP06DR2_WORKER").unwrap());assert_eq!(hash(&worker),std::env::var("LU_CP06DR2_WORKER_SHA256").unwrap());let f=F::new(ARCHIVE,None);let mut m=Scripted::new(&selection(Action::Archive),DONE);let r=f.review(f.propose(&mut m).unwrap().unwrap(),Some(worker)).unwrap();let result=r.execute(true,EFFECT,&f,&f.effects,&f.audit,&||f.live()).await.unwrap().unwrap();let answer=result.present(&mut m,&Cancellation::default(),&f.audit,&f.effects,&||f.live()).unwrap();f.check(Action::Archive,&answer,"model_selected_verified_effect_host_rendered");f.finish(&answer);f.cleanup()}
#[tokio::test]
#[ignore="requires pinned real local GGUF, llama-server, actual desktop archive worker, fixture human confirmation"]
async fn cp06dr2_genuine_publication(){use lu_core::{inference_supervisor::TrustedInferenceSupervisor,model_admission::ModelAdmissionManager,persistent_llama_backend::{PersistentEngineConfig,PersistentLlamaBackend},supervised_tool_generation::SupervisorModelStep};use std::{num::NonZeroUsize,time::Duration};
 let exe=PathBuf::from(std::env::var("LU_CP06D_SERVER").unwrap());let gguf=PathBuf::from(std::env::var("LU_CP06D_GGUF").unwrap());let esha=std::env::var("LU_CP06D_SERVER_SHA256").unwrap();let msha=std::env::var("LU_CP06D_GGUF_SHA256").unwrap();assert_eq!(hash(&exe),esha);assert_eq!(hash(&gguf),msha);let pin:[u8;32]=(0..esha.len()).step_by(2).map(|i|u8::from_str_radix(&esha[i..i+2],16).unwrap()).collect::<Vec<_>>().try_into().unwrap();let auth="deadbeef".repeat(8);let mut manager=ModelAdmissionManager::new();let admitted=manager.admit(gguf.parent().unwrap(),gguf.file_name().unwrap().to_str().unwrap()).unwrap().clone();let supervisor=TrustedInferenceSupervisor::new("llama-cpu".into(),8192,vec![("model-1".into(),admitted)],move||PersistentLlamaBackend::new(PersistentEngineConfig{executable:exe.clone(),expected_sha256:pin,threads:NonZeroUsize::new(3).unwrap(),context_tokens:8192,startup_timeout:Duration::from_secs(120),request_timeout:Duration::from_secs(120),api_key:auth.clone(),load_observer:None})).unwrap();let sid="cp06dr2-publication";supervisor.load("model-1",sid.into(),"cp06dr2-load").unwrap();assert!(supervisor.status().unwrap().pid.is_some());let base=PathBuf::from(std::env::var("LU_CP06D_EVIDENCE").unwrap());let worker=PathBuf::from(std::env::var("LU_CP06DR2_WORKER").unwrap());assert_eq!(hash(&worker),std::env::var("LU_CP06DR2_WORKER_SHA256").unwrap());
 for (i,(tag,s,a,approve)) in [("docx",DOC,Action::Docx,true),("pptx",SLIDE,Action::Pptx,true),("draft-docx",DRAFT_DOC,Action::Docx,true),("draft-pptx",DRAFT_SLIDE,Action::Pptx,true),("archive",ARCHIVE,Action::Archive,true),("decline",DOC,Action::Docx,false),("archive-decline",ARCHIVE,Action::Archive,false)].into_iter().enumerate(){let f=F::new(s,Some(base.join(tag)));let mut model=SupervisorModelStep::new(&supervisor,sid.into(),format!("pub-{i}")).unwrap();let p=f.propose(&mut model).unwrap().expect("genuine inert selection");assert_eq!(p.action(),a);let r=f.review(p,Some(worker.clone())).unwrap();let dest=f.folder.join(r.target());assert!(!dest.exists());let result=r.execute(approve,EFFECT,&f,&f.effects,&f.audit,&||f.live()).await.unwrap();if let Some(result)=result{assert!(approve);let answer=result.present(&mut model,&Cancellation::default(),&f.audit,&f.effects,&||f.live()).unwrap();f.check(a,&answer,"model_selected_verified_effect_host_rendered");f.finish(&answer);println!("CP06DR2_VERIFIED {tag} {answer}");}else{assert!(!approve);assert!(!dest.exists());assert!(f.effects.get(EFFECT).unwrap().is_none());f.finish("Publication declined. No output created.");println!("CP06DR2_DECLINED {tag}");}for e in f.audit.events_for(CHAT,TURN).unwrap(){println!("CP06DR2_AUDIT {tag} {:?} {}",e.kind,e.payload)}}supervisor.unload(sid,"cp06dr2-unload").unwrap();assert!(supervisor.status().unwrap().pid.is_none());}

// CP-06D-R3: original human intent -> model selection -> reviewed revision.
const WORD_SINGLE:&str=r#"Revise report.docx: replace "Heading" with "Revised heading"."#;
const WORD_BATCH:&str=r#"Revise report.docx: replace all "Before" with "After"."#;
const SLIDE_SINGLE:&str=r#"Revise deck.pptx: replace "Heading" with "Revised heading"."#;
const SLIDE_BATCH:&str=r#"Revise deck.pptx: replace all "Before" with "After"."#;
const CELL_SINGLE:&str="Revise budget.xlsx: change cell A1 on sheet 1 from 10 to 12.";
const CELL_BATCH:&str="Revise budget.xlsx: change cell A1 on sheet 1 from 10 to 12; change cell A2 on sheet 1 from true to false.";
fn revision_fixture(f:&F)->String{
 use lu_core::{native_docx_create::{render_docx,DocxBlock,DocxBlockKind},native_pptx_create::{render_pptx,PresentationSlide},native_spreadsheet_create::{render_xlsx,SpreadsheetCell,CellValue}};
 let (n,b)=if f.original.contains("report.docx"){("report.docx",render_docx(&[DocxBlock{kind:DocxBlockKind::Title,text:"Heading".into()},DocxBlock{kind:DocxBlockKind::Paragraph,text:"Before".into()},DocxBlock{kind:DocxBlockKind::Paragraph,text:"Before".into()},DocxBlock{kind:DocxBlockKind::Paragraph,text:"Unchanged".into()}]).unwrap())}else if f.original.contains("deck.pptx"){("deck.pptx",render_pptx(&[PresentationSlide{title:"Heading".into(),bullet_points:vec!["Before".into(),"Before".into(),"Unchanged".into()]}]).unwrap())}else{("budget.xlsx",render_xlsx("Budget",&[SpreadsheetCell{row:1,column:1,value:CellValue::Number(10.0)},SpreadsheetCell{row:2,column:1,value:CellValue::Boolean(true)},SpreadsheetCell{row:3,column:1,value:CellValue::Formula("SUM(A1:A1)".into())}]).unwrap())};fs::write(f.folder.join(n),b).unwrap();n.into()
}
fn revision_review(f:&F,p:Proposal,name:&str)->Result<Review,String>{let ext=name.rsplit_once('.').unwrap().1;let target=format!("revision.{ext}");p.review_revision(Arc::clone(&f.dir),name,name,Arc::clone(&f.dir),&target,&target,&f.audit)}
fn revision_check(f:&F,name:&str,target:&str,old:&str,answer:&str,count:usize){
 assert_eq!(hash(&f.folder.join(name)),old);let rows=f.audit.events_for(CHAT,TURN).unwrap();let preview:Value=serde_json::from_str(&rows[3].payload).unwrap();let record=f.effects.get(EFFECT).unwrap().unwrap();assert_eq!(record.state,EffectState::Applied);let receipt=record.receipt.unwrap();let digest=format!("{:x}",Sha256::digest(receipt));assert!(f.effects.independent_verified_receipt(EFFECT,&record.tool_id,&digest).unwrap());let got=hash(&f.folder.join(target));assert_eq!(preview["review"]["sha256"],got);let feedback:Value=serde_json::from_str(&rows[5].payload).unwrap();assert_eq!(feedback["observed"]["source_preserved"],true);assert_eq!(feedback["observed"]["changes"],count);assert!(answer.contains("original file unchanged"));assert!(rows.iter().all(|e|e.kind!=K::FinalAnswer));
 let parts=|path:&Path|{let mut z=zip::ZipArchive::new(fs::File::open(path).unwrap()).unwrap();let mut map=std::collections::BTreeMap::new();for i in 0..z.len(){let mut part=z.by_index(i).unwrap();let n=part.name().unwrap().into_owned();let mut b=Vec::new();part.read_to_end(&mut b).unwrap();map.insert(n,b);}map};let prior=parts(&f.folder.join(name));let next=parts(&f.folder.join(target));assert!(prior.keys().eq(next.keys()));for pair in preview["review"]["details"]["unaffected_parts"].as_array().unwrap(){let n=pair[0].as_str().unwrap();assert_eq!(prior[n],next[n]);}
 let primary=if name.ends_with("docx"){"word/document.xml"}else if name.ends_with("pptx"){"ppt/slides/slide1.xml"}else{"xl/worksheets/sheet1.xml"};let xml=std::str::from_utf8(&next[primary]).unwrap();if name.ends_with("xlsx"){assert!(xml.contains("<v>12</v>")&&xml.contains("SUM(A1:A1)"));assert!(xml.contains(if count==2{r#"<c r="A2" t="b"><v>0</v>"#}else{r#"<c r="A2" t="b"><v>1</v>"#}));}else if count==2{assert_eq!(xml.matches(">After<").count(),2);assert!(!xml.contains(">Before<")&&xml.contains(">Unchanged<"));}else{assert!(xml.contains(">Revised heading<")&&xml.contains(">Unchanged<"));}
}
#[tokio::test] async fn cp06dr3_exact_revision_and_batch_all_formats(){for (s,count) in [(WORD_SINGLE,1),(WORD_BATCH,2),(SLIDE_SINGLE,1),(SLIDE_BATCH,2),(CELL_SINGLE,1),(CELL_BATCH,2)]{let f=F::new(s,None);let name=revision_fixture(&f);let old=hash(&f.folder.join(&name));let a=if count==1{Action::Revision}else{Action::BatchRevision};let mut m=Scripted::new(&selection(a),DONE);let p=f.propose(&mut m).unwrap().unwrap();assert_eq!(p.action(),a);let r=revision_review(&f,p,&name).unwrap();let target=r.target().to_owned();assert!(r.modal().contains("original remains unchanged"));assert!(!f.folder.join(&target).exists());let v=r.execute(true,EFFECT,&f,&f.effects,&f.audit,&||f.live()).await.unwrap().unwrap();let answer=v.present(&mut m,&Cancellation::default(),&f.audit,&f.effects,&||f.live()).unwrap();revision_check(&f,&name,&target,&old,&answer,count);f.finish(&answer);f.cleanup();}}
