fn spreadsheet_check(f:&F,answer:&str){let a=Action::Xlsx;let rows=f.audit.events_for(CHAT,TURN).unwrap();let preview:Value=serde_json::from_str(&rows[3].payload).unwrap();let details=&preview["review"]["details"];assert_eq!(details["rows"],json!([["Item","Count","Active"],["=1+1",12,true],["Tea",-2,false]]));let feedback:Value=serde_json::from_str(&rows.iter().find(|r|r.kind==K::ToolFeedback).unwrap().payload).unwrap();let path=f.folder.join("output.xlsx");assert_eq!(hash(&path),feedback["observed"]["sha256"].as_str().unwrap());assert!(f.effects.independent_verified_receipt(EFFECT,a.tool(),feedback["receipt_sha256"].as_str().unwrap()).unwrap());let mut z=zip::ZipArchive::new(fs::File::open(path).unwrap()).unwrap();let mut sheet=String::new();z.by_name("xl/worksheets/sheet1.xml").unwrap().read_to_string(&mut sheet).unwrap();assert!(sheet.contains(r#"<c r="B2" t="n"><v>12</v></c>"#)&&sheet.contains(r#"<c r="C2" t="b"><v>1</v></c>"#)&&sheet.contains(r#"<c r="B3" t="n"><v>-2</v></c>"#)&&sheet.contains(r#"<c r="C3" t="b"><v>0</v></c>"#)&&!sheet.contains("<f>"));let mut strings=String::new();z.by_name("xl/sharedStrings.xml").unwrap().read_to_string(&mut strings).unwrap();assert!(strings.contains("=1+1")&&strings.contains("Tea"));assert!(answer.contains("Verified the exact approved package"));}
